import '../../App.css';
import React, { useMemo, useRef, useEffect, useContext, useState } from 'react';
import { Table, Form, InputNumber, Button, Popconfirm, Input, Checkbox } from 'antd';
import '../../index.css';

export default function TableForm(props_) {
    const {
        dataSource
        , setDataSource
        , defaultColumns = []
        , isRoundUp = false
        , footer = null
    } = props_;

    const [mealDays, setMealDays] = useState(20);
    const EditableContext = React.createContext(null);

    const formattedData = useMemo(() => {
        return dataSource.map((obj) =>
            Object.fromEntries(
                Object.entries(obj).map(([key, value]) => [
                    key,
                    Number.isFinite(value) ? value.toLocaleString() : value,
                ])
            )
        );
    }, [dataSource]);

    const sum = useMemo(() => {
        return dataSource.reduce((acc, obj) => {
            return Number.isFinite(obj.total) ? acc + obj.total : acc;
        }, 0);
    }, [dataSource]); // dataSource가 변경될 때만 계산

    useEffect(() => {

    }, []);

    const parseNumber = (value) => {
        if (typeof value === "string" && value.match(/^-?\d+(,\d{3})*(\.\d+)?$/)) {
            return Number(value.replace(/,/g, ""));
        }
        return value;
    };

    const EditableRow = ({ index, ...props }) => {
        const [form] = Form.useForm();
        return (
            <Form form={form} component={false}>
                <EditableContext.Provider value={form}>
                    <tr {...props} />
                </EditableContext.Provider>
            </Form>
        );
    };

    const EditableCell = ({
        title,
        editable,
        children,
        dataIndex,
        record,
        isNumber,
        handleSave,
        ...restProps
    }) => {

        const [editing, setEditing] = useState(false);
        const inputRef = useRef(null);
        const form = useContext(EditableContext);

        useEffect(() => {
            if (editing) {
                inputRef.current?.focus();
            }
        }, [editing]);

        const toggleEdit = () => {
            setEditing(!editing);
            form.setFieldsValue({
                [dataIndex]: parseNumber(record[dataIndex]),
            });
        };

        const save = async () => {
            try {
                const values = await form.validateFields();

                toggleEdit();
                handleSave({
                    ...record,
                    ...values,
                });
            } catch (errInfo) {
                console.log('Save failed:', errInfo);
            }
        };

        let childNode = children;
        if (editable) {
            childNode = editing ? (
                <Form.Item
                    style={{
                        margin: 0,
                    }}
                    name={dataIndex}
                    rules={[
                        {
                            required: true,
                            message: `값을 입력해주세요`,
                        },
                    ]}
                >
                    {
                        isNumber ?
                            <InputNumber min={0} style={{ width: '100%' }} ref={inputRef} onPressEnter={save} onBlur={save} />
                            :
                            <Input ref={inputRef} onPressEnter={save} onBlur={save} />
                    }

                </Form.Item>
            ) : (
                <div
                    className="editable-cell-value-wrap"
                    style={{
                        paddingInlineEnd: 24,
                    }}
                    onClick={toggleEdit}
                >
                    {children}
                </div>
            );
        }

        return <td {...restProps}>{childNode}</td>;
    };


    function roundUp(num1, num2, num3, roundingFactor = 100) {
        const result = num1 * num2 * num3;

        // roundingFactor의 자릿수로 올림
        const roundedResult = isRoundUp ? Math.ceil(result / roundingFactor) * roundingFactor : result;

        return roundedResult;
    }

    const components = {
        body: {
            row: EditableRow,
            cell: EditableCell,
        },
    };

    const handleSave = (row, col) => {
        const newData = [...dataSource];
        const index = newData.findIndex((item) => row.key === item.key);
        const item = newData[index];

        // row 객체의 모든 값에서 id는 제외하고 숫자 변환
        const parsedRow = Object.fromEntries(
            Object.entries(row).map(([key, value]) => [key, key === 'key' ? value : parseNumber(value)])
        );

        newData.splice(index, 1, {
            ...item,
            ...parsedRow,
            total: roundUp(parsedRow.price, parsedRow.date, parsedRow.count, parsedRow.key === "1" ? 1000 : 100),
            sumTotal: (parsedRow?.price1 || 0) + (parsedRow?.price2 || 0) + (parsedRow?.price3 || 0),
        });

        setDataSource(newData);
    };

    const columns = defaultColumns.map((col) => {
        if (!col.editable) {
            return col;
        }
        return {
            ...col,
            onCell: (record) => ({
                record,
                editable: col.editable,
                dataIndex: col.dataIndex,
                title: col.title,
                isNumber: col.isNumber,
                handleSave,
            }),
        };
    });

    const onChange = (pagination, filters, sorter, extra) => {
        // console.log('params', pagination, filters, sorter, extra);
    };

    const onChangeDate = (value) => {
        setMealDays(value);
        setDataSource((prevData) =>
            prevData.map((obj) => (
                obj.isAllAdapt ? { ...obj, date: value, total: roundUp(obj.price, value, obj.count, obj.key === '1' ? 1000 : 100) } : obj
            ))
        );
    };

    const handleAdd = () => {
        let newData = {};

        if (dataSource.length > 0) {
            newData = { ...dataSource[dataSource.length - 1], key: `${dataSource.length + 1}` };
        } else {
            newData = defaultColumns.reduce((acc, col) => {
                acc[col.dataIndex] = ''; // dataIndex를 키로 하고 빈 문자열 할당
                return acc;
            }, { key: '1' });
        }

        setDataSource([...dataSource, newData]);
    };

    return (
        <>
            <div style={{ display: "flex", justifyContent: "space-between", width: "100%", marginBottom: "5px" }}>
                <div>
                    <Button
                        onClick={handleAdd}
                        type="primary"
                        style={{
                            marginBottom: 16,
                        }}
                    >
                        Add a row
                    </Button>
                </div>
                <div>
                    급식일수 : <InputNumber min={1} defaultValue={mealDays} onChange={onChangeDate} />
                </div>
            </div>

            <div style={{ width: "100%", height: "90%" }}>

                <Table
                    pagination={false}
                    size="middle"
                    components={components}
                    rowClassName={() => 'editable-row'}
                    columns={columns}
                    dataSource={formattedData}
                    onChange={onChange}
                    footer={footer ? () => {
                        return footer
                    } : null}
                />

            </div>
        </>
    )
}


