import '../../App.css';
import React, { useRef, useMemo, useEffect, useState } from 'react';
import axios from "axios";
import { DatePicker, Button, notification, Spin, Divider, Tabs, Checkbox, Popconfirm, Alert } from 'antd';
import TableForm from './TableForm';
import dayjs from 'dayjs';
import 'dayjs/locale/ko';
import { HeartTwoTone } from '@ant-design/icons';
import '../../index.css';


export default function CalculateCreate(props_) {
  const [api, contextHolder] = notification.useNotification();

  const currentMonth = dayjs().month();  // 현재 달을 0부터 시작하는 값으로 가져옴
  const currentYear = dayjs().year();

  const [selectedDate, setSelectedDate] = useState(dayjs(`${currentYear}-${currentMonth + 1}-01`))
  const [quarter, setQuarter] = useState(String(currentMonth === 0 ? currentYear - 1 : currentYear));

  const [fullDataSource, setFullDataSource] = useState([]);
  const [dataSource, setDataSource] = useState([]);
  const [formatDataSource, setFormatDataSource] = useState([]);

  const [calculateAllData, setCalculateAllData] = useState([]);

  const [activeKey, setActiveKey] = useState('expense');

  const defaultColumns = [
    {
      title: '구분',
      dataIndex: 'schoolName',
      editable: true,
      width: '10%',
    },
    {
      title: '업체군',
      dataIndex: 'class',
      editable: true,
      width: '10%',
    },

    {
      title: '낙찰금액',
      dataIndex: 'price1',
      editable: true,
      width: '15%',
      isNumber: true,
    },
    {
      title: '학교자부담',
      dataIndex: 'price2',
      editable: true,
      width: '15%',
      isNumber: true,
    },
    {
      title: '보조금',
      dataIndex: 'price3',
      editable: true,
      width: '15%',
      isNumber: true,
    },

    {
      title: '총계',
      dataIndex: 'sumTotal',
      width: '15%',
      isNumber: true,
    },
    {
      title: '추가 기능',
      dataIndex: 'operation',
      width: '10%',
      render: (_, record) =>
        dataSource.length >= 1 ? (
          <Popconfirm title="Sure to delete?" onConfirm={() => handleDelete(record.key)}>
            <a>Delete</a>
          </Popconfirm>
        ) : null,
    }
  ];


  const defaultColumns1 = [
    {
      title: '회천',
      dataIndex: 'schoolName',
      editable: true,
      width: '10%',
    },
    {
      title: '급',
      dataIndex: 'class',
      editable: true,
      width: '20%',
    },
    {
      title: '식품비',
      dataIndex: 'price',
      editable: true,
      width: '15%',
      isNumber: true,
    },
    {
      title: '급식일수 일괄적용',
      dataIndex: 'isAllAdapt',
      width: '5%',
      render: (_, record) => <Checkbox checked={record.isAllAdapt} onChange={(e) => {
        setDataSource((prevData) =>
          prevData.map((item) =>
            item.key === record.key ? { ...item, isAllAdapt: e.target.checked } : item
          )
        );
      }} />,
    },
    {
      title: '급식일수',
      dataIndex: 'date',
      editable: true,
      width: '10%',
      isNumber: true,
    },
    {
      title: '학생 수',
      dataIndex: 'count',
      editable: true,
      width: '10%',
      isNumber: true,
    },
    {
      title: '총액',
      dataIndex: 'total',
      width: '15%',
      isNumber: true,
    },
    {
      title: '추가 기능',
      dataIndex: 'operation',
      width: '10%',
      render: (_, record) =>
        dataSource.length >= 1 ? (
          <Popconfirm title="Sure to delete?" onConfirm={() => handleDelete(record.key)}>
            <a>Delete</a>
          </Popconfirm>
        ) : null,
    }
  ];

  const defaultColumns2 = [
    {
      title: '구분',
      dataIndex: 'schoolName',
      editable: true,
      width: '10%',
    },
    {
      title: '보조/자부담',
      dataIndex: 'assistance',
      editable: true,
      width: '10%',
    },
    {
      title: '급',
      dataIndex: 'class',
      editable: true,
      width: '15%',
    },
    {
      title: '식품비',
      dataIndex: 'price',
      editable: true,
      width: '15%',
      isNumber: true,
    },
    {
      title: '급식일수 일괄적용',
      dataIndex: 'isAllAdapt',
      width: '5%',
      render: (_, record) => <Checkbox checked={record.isAllAdapt} onChange={(e) => {
        setDataSource((prevData) =>
          prevData.map((item) =>
            item.key === record.key ? { ...item, isAllAdapt: e.target.checked } : item
          )
        );
      }} />,
    },
    {
      title: '급식일수',
      dataIndex: 'date',
      editable: true,
      width: '10%',
      isNumber: true,
    },
    {
      title: '학생 수',
      dataIndex: 'count',
      editable: true,
      width: '10%',
      isNumber: true,
    },
    {
      title: '총액',
      dataIndex: 'total',
      width: '15%',
      isNumber: true,
    },

    {
      title: '추가 기능',
      dataIndex: 'operation',
      width: '10%',
      render: (_, record) =>
        dataSource.length >= 1 ? (
          <Popconfirm title="Sure to delete?" onConfirm={() => handleDelete(record.key)}>
            <a>Delete</a>
          </Popconfirm>
        ) : null,
    }

  ];

  const defaultColumns3 = [
    {
      title: '회천',
      dataIndex: 'schoolName',
      editable: true,
      width: '10%',
    },
    {
      title: '급',
      dataIndex: 'class',
      editable: true,
      width: '20%',
    },
    {
      title: '운영비',
      dataIndex: 'price',
      editable: true,
      width: '15%',
      isNumber: true,
    },
    {
      title: '급식일수 일괄적용',
      dataIndex: 'isAllAdapt',
      width: '5%',
      render: (_, record) => <Checkbox checked={record.isAllAdapt} onChange={(e) => {
        setDataSource((prevData) =>
          prevData.map((item) =>
            item.key === record.key ? { ...item, isAllAdapt: e.target.checked } : item
          )
        );
      }} />,
    },
    {
      title: '급식일수',
      dataIndex: 'date',
      editable: true,
      width: '10%',
      isNumber: true,
    },
    {
      title: '학생 수',
      dataIndex: 'count',
      editable: true,
      width: '10%',
      isNumber: true,
    },
    {
      title: '총액',
      dataIndex: 'total',
      width: '15%',
      isNumber: true,
    },
    {
      title: '추가 기능',
      dataIndex: 'operation',
      width: '10%',
      render: (_, record) =>
        dataSource.length >= 1 ? (
          <Popconfirm title="Sure to delete?" onConfirm={() => handleDelete(record.key)}>
            <a>Delete</a>
          </Popconfirm>
        ) : null,
    }
  ];

  const sum = useMemo(() => {
    return dataSource.reduce((acc, obj) => {
      if (activeKey === 'expense') {
        return Number.isFinite(obj.price1) && Number.isFinite(obj.price2) ? acc + obj.price1 + obj.price2 : acc;
      } else {
        return Number.isFinite(obj.total) ? acc + obj.total : acc;
      }

    }, 0);
  }, [dataSource]); // dataSource가 변경될 때만 계산

  const ecoSum = useMemo(() => {
    return dataSource.reduce((acc, obj) => {
      if (obj.schoolName === "친환경") {
        return Number.isFinite(obj.price2) ? acc + obj.price2 : acc;
      } else {
        return acc;
      }

    }, 0);
  }, [dataSource]); // dataSource가 변경될 때만 계산

  const getAllSum = (tabKey, column="sum") => {
    const targetDbData = calculateAllData.find((item) => item.key === tabKey)?.allDbData || [];
  
    return targetDbData.reduce((acc, obj) => Number.isFinite(obj[column]) ? acc + obj[column] : acc, 0);
  };
  

  const customTotal = (schoolName, assistance) => {
    return dataSource.filter(item => item.schoolName === schoolName && item.assistance === assistance).reduce((acc, obj) => {
      return Number.isFinite(obj.total) ? acc + obj.total : acc;
    }, 0)
  }

  const getCellValue = (tabKey, column, filterColumn = null, filterValue = null) => {
    const targetAllData = calculateAllData.find((item) => item.key === tabKey)?.allDbData.find((item) => item.key === selectedDate.format("YYYY-MM"))?.data || []

    return targetAllData.reduce((acc, obj) => {
      if (filterColumn && filterValue) {
        if (obj[filterColumn] === filterValue) {
          return Number.isFinite(obj[column]) ? acc + obj[column] : acc;
        } else {
          return acc;
        }
      } else {
        return Number.isFinite(obj[column]) ? acc + obj[column] : acc;
      }
    }, 0);
  }

  const items = [
    {
      key: 'expense',
      label: '세출',
      children: (
        <TableForm
          dataSource={dataSource}
          setDataSource={setDataSource}
          defaultColumns={defaultColumns}
          footer={
            <div>
              <div className="footer-container" style={{ marginBottom: "2px" }}>
                <div className="empty-space">친환경 총계</div>
                <div className="text">{ecoSum.toLocaleString()}</div>
              </div>

              <div className="footer-container" style={{ marginBottom: "2px" }}>
                <div className="empty-space">지출액</div>
                <div className="text">{sum.toLocaleString()}</div>
              </div>

              <div className="footer-container" style={{ marginBottom: "2px" }}>
                <div className="empty-space">결산</div>
                <div className="text">
                  <span className={`footer-value ${(getCellValue("foodIncome", "total") - sum) > 0 ? "plus" : "minus"}`}>
                    {(getCellValue("foodIncome", "total") - sum).toLocaleString()}
                  </span>
                </div>
              </div>
            </div>
          }
        />
      ),
    },
    {
      key: 'foodIncome',
      label: '식품비',
      children: (
        <TableForm
          dataSource={dataSource}
          setDataSource={setDataSource}
          defaultColumns={defaultColumns1}
          footer={
            <div>
              <div className="footer-container" style={{ marginBottom: "2px" }}>
                <div className="empty-space">세입</div>
                <div className="text">{sum.toLocaleString()}</div>
              </div>
            </div>
          }
        // isRoundUp={true}
        />
      ),
    },
    {
      key: 'foodIncomeEco',
      label: '친환경',
      children: (<TableForm
        dataSource={dataSource}
        setDataSource={setDataSource}
        defaultColumns={defaultColumns2}
        footer={
          <div>
            <div className="footer-container" style={{ marginBottom: "2px" }}>
              <div className="empty-space">친환경-보조금</div>
              <div className="text">{customTotal('친환경', '보조금').toLocaleString()}</div>
            </div>

            <div className="footer-container" style={{ marginBottom: "2px" }}>
              <div className="empty-space">친환경-자부담</div>
              <div className="text">{customTotal('친환경', '자부담').toLocaleString()}</div>
            </div>

            <div className="footer-container" style={{ marginBottom: "2px" }}>
              <div className="empty-space">Non-GMO</div>
              <div className="text">{customTotal('Non-GMO', '보조금').toLocaleString()}</div>
            </div>

            <div className="footer-container" style={{ marginTop: "10px", marginBottom: "2px", border: "1px solid red" }}>
              <div className="empty-space">친환경 결산</div>
              <div className="text">
                <span className={`footer-value ${((customTotal('친환경', '자부담') - getCellValue("expense", "price2", "schoolName", "친환경"))) > 0 ? "plus" : "minus"}`}>
                  {(customTotal('친환경', '자부담') - getCellValue("expense", "price2", "schoolName", "친환경")).toLocaleString()}
                </span>
              </div>

            </div>

            <div className="footer-container" style={{ marginBottom: "2px", border: "1px solid red" }}>
              <div className="empty-space">Non-GMO 결산</div>
              <div className="text">
                <span className={`footer-value ${(customTotal('Non-GMO', '보조금') - getCellValue("expense", "price3", "class", "Non-GMO")) > 0 ? "plus" : "minus"}`}>
                  {(customTotal('Non-GMO', '보조금') - getCellValue("expense", "price3", "class", "Non-GMO")).toLocaleString()}
                </span>
              </div>
            </div>

          </div>
        }
      />),
    },
    {
      key: 'operatingCost',
      label: '운영비',
      children: (<TableForm
        dataSource={dataSource}
        setDataSource={setDataSource}
        defaultColumns={defaultColumns3}
        footer={
          <div>
            <div className="footer-container" style={{ marginBottom: "2px" }}>
              <div className="empty-space">세입</div>
              <div className="text">{sum.toLocaleString()}</div>
            </div>
          </div>
        }
      />),
    },
  ];

  useEffect(() => {
    getAllCalculateData(items.map((obj) => {
      return {key: obj.key, label: obj.label, fileName: `${obj.key}Data.json`}
    }));

  // }, [selectedDate]);
  }, [quarter]);

  useEffect(() => {
    getCalculateData();
    getFormat();
  }, [activeKey]);

  const getCalculateData = (dateKey = selectedDate.format("YYYY-MM")) => {
    const parameter = {
      folderName: 'db',
      fileName: `${activeKey}Data.json`
    };

    axios.post('http://localhost:5000/getFileData', parameter)
      .then(res => {
        const currentData = res.data.find(item => item.key === dateKey)?.data ?? [];
        setFullDataSource(res.data);
        setDataSource(currentData);
      })
      .catch(error => {
        setFullDataSource([]);
        setDataSource([]);
        console.error(error);
      });
  }

  const getAllCalculateData = (fileArray, dateKey = selectedDate.format("YYYY-MM")) => {
    const parameter = {
      folderName: 'db',
      fileArray: fileArray,
      selectedDate : dateKey,
      quarter: quarter,
    };

    axios.post('http://localhost:5000/getMultiFileData', parameter)
      .then(res => {
        const newAllDbData = res.data.map((item) => {
          const db = item.allDbData.map((target) => {
            // 일반 sum 계산
            const sumTotal = target.data.reduce((acc, obj) => {
              if (item.key === 'expense') {
                return Number.isFinite(obj.price1) && Number.isFinite(obj.price2)
                  ? acc + obj.price1 + obj.price2
                  : acc;
              } else if (item.key === 'foodIncomeEco') {
                // foodIncomeEco일 경우에는 여기서 sum 계산 안 하고 건너뜀
                return acc;
              } else {
                return Number.isFinite(obj.total) ? acc + obj.total : acc;
              }
            }, 0);
        
            // ecoSum 계산 (expense, foodIncomeEco일 때만)
            const ecoSum = item.key === 'foodIncomeEco'
              ? target.data.reduce((acc, obj) => {
                return obj.schoolName === '친환경' &&
                  obj.assistance === '자부담' &&
                  Number.isFinite(obj.total)
                  ? acc + obj.total
                  : acc;
              }, 0)
              :
              item.key === 'expense' ?
                target.data.reduce((acc, obj) => {
                  return obj.schoolName === '친환경' && Number.isFinite(obj.price2)
                    ? acc + obj.price2
                    : acc;
                }, 0)
              : undefined;


            // nonGmoSum 계산 (expense, foodIncomeEco일 때만)
            const nonGmoSum = item.key === 'foodIncomeEco'
              ? target.data.reduce((acc, obj) => {
                return obj.schoolName === 'Non-GMO' &&
                       obj.assistance === '보조금' &&
                       Number.isFinite(obj.total)
                  ? acc + obj.total
                  : acc;
              }, 0)
              :
              item.key === 'expense' ?
                target.data.reduce((acc, obj) => {
                  return obj.class === 'Non-GMO' && Number.isFinite(obj.price3)
                    ? acc + obj.price3
                    : acc;
                }, 0)
              : undefined;

            return {
              ...target,
              ...(item.key === 'foodIncomeEco' || item.key === 'expense' ? { ecoSum : ecoSum, nonGmoSum : nonGmoSum, sum: sumTotal } : { sum: sumTotal })
            };
          });
        
          return {
            ...item,
            allDbData: db
          };
        });

        console.log(newAllDbData);

        setCalculateAllData(newAllDbData);
      })
      .catch(error => {
        setCalculateAllData([]);
        console.error(error);
      });
  }

  const getFormat = () => {
    const parameter = {
      folderName: 'db',
      fileName: `${activeKey}Format.json`
    };

    axios.post('http://localhost:5000/getFileData', parameter)
      .then(res => {
        setFormatDataSource(res.data);
      })
      .catch(error => {
        console.error(error);
      });
  }

  const onChangeCurrentDate = (date, dateString) => {
    const year = date?.year();
    const month = date?.month();

    // 회계연도 계산: 2월~12월이면 현재 year, 1월이면 전년도
    const fiscalYear = (month === 0) ? year - 1 : year;

    console.log(fiscalYear);
    setQuarter(String(fiscalYear));

    setSelectedDate(date);
    getCalculateData(dateString);
  };


  const handleFetchFormat = () => {
    setDataSource(formatDataSource);
  };

  const handleSave = () => {
    const dateKey = selectedDate.format("YYYY-MM");

    // dateKey가 fullDataSource에 존재하는지 확인
    const exists = fullDataSource.some((obj) => obj.key === dateKey);

    // 만약 존재하면 업데이트, 없으면 새 객체 추가
    const updatedDataSource = exists
      ? fullDataSource.map((obj) =>
        obj.key === dateKey ? { ...obj, data: dataSource } : obj
      )
      : [...fullDataSource, { key: dateKey, data: dataSource }];

    const parameter = {
      folderName: "db",
      fileName: `${activeKey}Data.json`,
      data: updatedDataSource,
    };

    axios.post("http://localhost:5000/setFileData", parameter)
      .then((response) => {
        setFullDataSource(updatedDataSource);
        openNotification();
        getAllCalculateData(items.map((obj) => {
          return {key: obj.key, label: obj.label, fileName: `${obj.key}Data.json`}
        }));
      })
      .catch((error) => {
        console.error(error);
        openNotification(false);
      });
  };


  const openNotification = (isSuccess = true) => {
    api.success({
      message: isSuccess ? '저장 완료' : '저장 실패',
      description:
        isSuccess ? '저장이 완료되었습니다.' : '저장에 실패했습니다.',
      placement: 'top',
      duration: 2,
    });
  };

  const cellRender = (current) => {
    const selectedMonthFormat = selectedDate.format("YYYY-MM");
    const targetMonthFormat = current.format("YYYY-MM");
    const hasDataForMonth = fullDataSource.find(item => item.key === targetMonthFormat);

    return (
      <div style={{ textAlign: "center", position: "relative" }}>
        <span className={`date-picker ${selectedMonthFormat === targetMonthFormat ? 'selected-date' : ''}`}>
          {current.month() + 1}월
        </span>
        {hasDataForMonth && (
          <span style={{
            fontSize: "15px",
            color: "red",
            position: "absolute",
            bottom: -25,
            left: "50%",
            transform: "translateX(-50%)",
          }}>
            <HeartTwoTone twoToneColor="#eb2f96" />
          </span>
        )}
      </div>
    );
  };


  const handleDelete = (key) => {
    const newData = dataSource.filter((item) => item.key !== key);
    setDataSource(newData);
  };

  const onChange = key => {
    setActiveKey(key);
  };

  return (
    <>
      <div style={{marginBottom : "10px"}}>
        <Alert
          type="info"
          message={
              <div style={{ textAlign: "center" }}>
                <span className='title-vertical'>
                  <span className='bold-font' style={{ marginRight : "10px", color : "#1f7afb"}}>{`[${quarter} (2)3월 ~ ${Number(quarter) + 1}년 1월]`}</span>
                  <span className='bold-font'>*식품비 결산</span> : {(getAllSum('foodIncome') - getAllSum('expense')).toLocaleString()}
                </span>
                <span className='title-vertical'>
                  <span className='bold-font'>*(친환경 결산) 자부담</span> : {(getAllSum('foodIncomeEco', 'ecoSum') - getAllSum('expense', 'ecoSum')).toLocaleString()}
                </span>
                <span className='title-vertical'>
                  <span className='bold-font'>*(Non-GMO 결산) 보조금 </span>: {(getAllSum('foodIncomeEco', 'nonGmoSum') - getAllSum('expense', 'nonGmoSum')).toLocaleString()}
                </span>
                <span className='title-vertical'>
                  <span className='bold-font'>총계 </span>: {((getAllSum('foodIncome') - getAllSum('expense')) - (getAllSum('foodIncomeEco', 'ecoSum') - getAllSum('expense', 'ecoSum'))).toLocaleString()}
                </span>
              </div>
          } />
      </div>

      <div style={{ display: "flex", justifyContent: "space-between", width: "100%", marginBottom: "15px", marginTop: "5px" }}>
        <h2 style={{ margin: 0 }}>
          {selectedDate.format("YYYY년 MM월")} 등록
        </h2>

        <div style={{ display: "flex", justifyContent: "end" }}>
          <Button
            onClick={handleFetchFormat}
            type="primary"
            style={{
              marginRight: 7,
            }}
          >
            포맷 불러오기
          </Button>

          <DatePicker value={selectedDate} picker="month" cellRender={cellRender} onChange={onChangeCurrentDate} />
        </div>
      </div>

      <Tabs defaultActiveKey="1" items={items} onChange={onChange} activeKey={activeKey} />

      <div style={{ display: "flex", justifyContent: "end", width: "100%", margin: "15px 0" }}>
        <Button type="primary" onClick={handleSave}>저장</Button>
      </div>

      {contextHolder}
    </>
  )
}


