import '../../App.css';
import axios from "axios";
import React, { useMemo, useRef, useEffect, useContext, useState } from 'react';
import { Table, Form, InputNumber, Button, Popconfirm, Input, Checkbox, DatePicker, Tabs } from 'antd';
import dayjs from 'dayjs';
import 'dayjs/locale/ko';
import '../../index.css';
import { DEFAULT_COLUMN, ECO_COLUMN, NON_GMO_COLUMN, FOOD_INCOME_TOTAL_COLUMN, OPERATING_INCOME_TOTAL_COLUMN } from '../columnList/OutputColumns';

export default function OutputPage(props_) {
    const {

    } = props_;

    const currentMonth = dayjs().month();  // 현재 달을 0부터 시작하는 값으로 가져옴
    const currentYear = dayjs().year();

    const [quarter, setQuarter] = useState(String(currentMonth === 0 ? currentYear - 1 : currentYear));
    const [calculateAllData, setCalculateAllData] = useState([]);

    const [expenseData, setExpenseData] = useState([]);
    const [foodIncomeData, setFoodIncomeData] = useState([]);
    const [foodIncomeEcoData, setFoodIncomeEcoData] = useState([]);
    const [operatingCost, setOperatingCost] = useState([]);

    const [activeKey, setActiveKey] = useState('foodExpense');

    const items = [
        {
            key: 'expense',
            label: '세출',
        },
        {
            key: 'foodIncome',
            label: '식품비',
        },
        {
            key: 'foodIncomeEco',
            label: '친환경',
        },
        {
            key: 'operatingCost',
            label: '운영비',
        },
    ];

    useEffect(() => {
        getAllCalculateData(items.map((obj) => {
            return { key: obj.key, label: obj.label, fileName: `${obj.key}Data.json` }
        }));
    }, [quarter]);


    const getAllCalculateData = (fileArray, dateKey = quarter) => {
        const parameter = {
            folderName: 'db',
            fileArray: fileArray,
            selectedDate: dateKey,
            quarter: quarter,
        };

        axios.post('http://localhost:5000/getMultiFileData', parameter)
            .then(res => {
                setCalculateAllData(res.data);

                const expenseData = res.data.find((obj) => obj.key === "expense").allDbData;
                const foodIncomeData = res.data.find((obj) => obj.key === "foodIncome").allDbData;
                const foodIncomeEcoData = res.data.find((obj) => obj.key === "foodIncomeEco").allDbData;
                const operatingCostData = res.data.find((obj) => obj.key === "operatingCost").allDbData;

                const newExpenseData = expenseData.map((elm) => {
                    const data = elm.data || [];

                    const normal = data.find(item => item.class.trim() === "일반") || {};
                    const meat = data.find(item => item.class.trim() === "육류") || {};
                    const ecoMeat = data.find(item => item.class.trim() === "친환경육류") || {};
                    const nonGMO = data.find(item => item.class.trim() === "Non-GMO") || {};

                    const ecoSum = elm.data.reduce((acc, obj) => {
                        if (obj.schoolName.trim() === "친환경") {
                            return Number.isFinite(obj.price2) ? acc + obj.price2 : acc;
                        } else {
                            return acc;
                        }
                    }, 0);
                    const ecoSubsidySum = elm.data.reduce((acc, obj) => {
                        if (obj.schoolName.trim() === "친환경") {
                            return Number.isFinite(obj.price3) ? acc + obj.price3 : acc;
                        } else {
                            return acc;
                        }
                    }, 0);

                    const price1_normal = normal.price1 || 0;
                    const price1_meat = meat.price1 || 0;
                    const price2_nonGMO = nonGMO.price2 || 0;
                    const nonGmoSubsidy = nonGMO.price3 || 0;

                    const eco = ecoSum || 0;
                    const price2_eco_meat = ecoMeat.price2 || 0;
                    const price3_eco_meat = ecoMeat.price3 || 0;

                    const newObj = {
                        key: elm.key,
                        date: elm.key,
                        count: 0,
                        normal: price1_normal.toLocaleString(),
                        meats: price1_meat.toLocaleString(),
                        generalMeats: (price1_normal + price1_meat).toLocaleString(),
                        ecoSelf: eco.toLocaleString(),
                        nonGmoSelf: price2_nonGMO.toLocaleString(),
                        amountSpent: (price1_normal + price1_meat + eco + price2_nonGMO).toLocaleString(),
                        ecoSubsidy: ecoSubsidySum.toLocaleString(),
                        ecoTotal: (ecoSubsidySum + eco).toLocaleString(),
                        ecoMeat: (price2_eco_meat + price3_eco_meat).toLocaleString(),
                        nonGmoSubsidy: nonGmoSubsidy.toLocaleString(),
                        nonGmoSum: (nonGmoSubsidy + price2_nonGMO).toLocaleString(),
                    };

                    return newObj
                })


                const newFoodIncomeData = foodIncomeData.map((elm) => {
                    const data = elm.data || [];

                    const kindy1Info = data.find(item => item.class.trim() === "유치원") || {};
                    const kindy2Info = data.filter(item => item.class.trim() === "유치원")?.[1] || {};
                    const elemStudentInfo = data.find(item => item.class.trim() === "초등") || {};

                    const kindyFreeFoodCost = kindy1Info.total || 0;
                    const kindyEduFoodCost = kindy2Info.total || 0;
                    const elemFoodCost = elemStudentInfo.total || 0;

                    const staffFoodCost = elm.data.reduce((acc, obj) => {
                        if (obj.class.trim() !== "유치원" && obj.class.trim() !== "초등") {
                            return Number.isFinite(obj.total) ? acc + obj.total : acc;
                        } else {
                            return acc;
                        }
                    }, 0);

                    const newObj = {
                        date: 0,
                        mealDays: 0,
                        elemStudentCount: 0,
                        elemFoodCost: elemFoodCost.toLocaleString(),
                        staffFoodCost: staffFoodCost.toLocaleString(),
                        kindyFoodCost: (kindyFreeFoodCost + kindyEduFoodCost).toLocaleString(),
                        kindyFreeFoodCost: kindyFreeFoodCost.toLocaleString(),
                        kindyEduFoodCost: kindyEduFoodCost.toLocaleString(),
                        kindyDays: 0,
                        kindyKidCount: 0,
                    }

                    return newObj;
                })

                const newOperatingCost =  operatingCostData.map((elm) => {
                    const data = elm.data || [];

                    const kindy1Info = data.find(item => item.class.trim() === "유치원") || {};
                    const kindy2Info = data.filter(item => item.class.trim() === "유치원")?.[1] || {};
                    const elemStudentInfo = data.find(item => item.class.trim() === "초등") || {};



                    const kindyFreeOperatingCost = kindy1Info.total || 0;
                    const kindyEduOperatingCost = kindy2Info.total || 0;
                    const elemOperatingCost = elemStudentInfo.total || 0;

                    const staffOperatingCost = elm.data.reduce((acc, obj) => {
                        if (obj.class.trim() !== "유치원" && obj.class.trim() !== "초등") {
                            return Number.isFinite(obj.total) ? acc + obj.total : acc;
                        } else {
                            return acc;
                        }
                    }, 0);

                    const newObj = {
                        date: 0,
                        mealDays: 0,
                        elemStudentCount: 0,
                        elemOperatingCost: elemOperatingCost.toLocaleString(),
                        staffOperatingCost: staffOperatingCost.toLocaleString(),
                        kindyOperatingCost: (kindyFreeOperatingCost + kindyEduOperatingCost).toLocaleString(),
                        kindyFreeOperatingCost: kindyFreeOperatingCost.toLocaleString(),
                        kindyEduOperatingCost: kindyEduOperatingCost.toLocaleString(),
                        kindyDays: 0,
                        kindyKidCount: 0,
                    }

                    return newObj;
                })

                setExpenseData(newExpenseData);
                setFoodIncomeData(newFoodIncomeData);
                setOperatingCost(newOperatingCost);

            })
            .catch(error => {
                setCalculateAllData([]);
                console.error(error);
            });
    }

    const onChange = (date, dateString) => {
        setQuarter(dateString);
    };

    const onChangeTab = key => {
        setActiveKey(key);
    };

    const tabItems = [
        {
            key: 'foodExpense',
            label: '식품비 세출',
            children: (
                <div>
                    <div style={{ display: "flex", justifyContent: "space-between", width: "100%", marginBottom: "15px", marginTop: "5px" }}>
                        <h2 style={{ margin: "3px" }}>식품비 총 세출</h2>
                        <div style={{ display: "flex", justifyContent: "end" }}>
                            <DatePicker onChange={onChange} picker="year" value={dayjs(quarter, 'YYYY')} format={'YYYY'} />
                        </div>
                    </div>

                    <div style={{ display: "flex", justifyContent: "space-between", width: "100%", marginBottom: "15px", marginTop: "5px" }}>
                        <h3 style={{ margin: "3px" }}>식품비 세출</h3>
                    </div>
                    <Table columns={DEFAULT_COLUMN} dataSource={expenseData} />

                    <div style={{ display: "flex", justifyContent: "space-between", width: "100%", marginBottom: "15px", marginTop: "5px" }}>
                        <h3 style={{ margin: "3px" }}>친환경 세출</h3>
                    </div>
                    <Table columns={ECO_COLUMN} dataSource={expenseData} />

                    <div style={{ display: "flex", justifyContent: "space-between", width: "100%", marginBottom: "15px", marginTop: "5px" }}>
                        <h3 style={{ margin: "3px" }}>Non-gmo 세출</h3>
                    </div>
                    <Table columns={NON_GMO_COLUMN} dataSource={expenseData} />
                </div>
            ),
        },
        {
            key: 'foodIncome',
            label: '식품비 세출(예산별)',
            children: (
                <div>
                    <div style={{ display: "flex", justifyContent: "space-between", width: "100%", marginBottom: "15px", marginTop: "5px" }}>
                        <h2 style={{ margin: "3px" }}>식품비 총 세출(예산별)</h2>
                        <div style={{ display: "flex", justifyContent: "end" }}>
                            <DatePicker onChange={onChange} picker="year" value={dayjs(quarter, 'YYYY')} format={'YYYY'} />
                        </div>
                    </div>

                    <div style={{ display: "flex", justifyContent: "space-between", width: "100%", marginBottom: "15px", marginTop: "5px" }}>
                        <h3 style={{ margin: "3px" }}>식품비 세출</h3>
                    </div>
                    <Table columns={DEFAULT_COLUMN} dataSource={expenseData} />

                    <div style={{ display: "flex", justifyContent: "space-between", width: "100%", marginBottom: "15px", marginTop: "5px" }}>
                        <h3 style={{ margin: "3px" }}>식품비 세입</h3>
                    </div>
                    <Table columns={ECO_COLUMN} dataSource={[]} />
                </div>
            ),
        },
        {
            key: 'foodIncomeEco',
            label: '식품비 세입',
            children: (
                <div>
                    <div style={{ display: "flex", justifyContent: "space-between", width: "100%", marginBottom: "15px", marginTop: "5px" }}>
                        <h2 style={{ margin: "3px" }}>식품비 총 세입</h2>
                        <div style={{ display: "flex", justifyContent: "end" }}>
                            <DatePicker onChange={onChange} picker="year" value={dayjs(quarter, 'YYYY')} format={'YYYY'} />
                        </div>
                    </div>

                    <Table columns={FOOD_INCOME_TOTAL_COLUMN} dataSource={foodIncomeData} />
                </div>
            ),
        },
        {
            key: 'operatingCost',
            label: '운영비 세입',
            children: (
                <div>
                    <div style={{ display: "flex", justifyContent: "space-between", width: "100%", marginBottom: "15px", marginTop: "5px" }}>
                        <h2 style={{ margin: "3px" }}>운영비 총 세입</h2>
                        <div style={{ display: "flex", justifyContent: "end" }}>
                            <DatePicker onChange={onChange} picker="year" value={dayjs(quarter, 'YYYY')} format={'YYYY'} />
                        </div>
                    </div>

                    <Table columns={OPERATING_INCOME_TOTAL_COLUMN} dataSource={operatingCost} />
                </div>
            ),
        },
        {
            key: 'budget',
            label: '예산',
            children: (
                <div></div>
            ),
        },
    ];

    return (
        <>
            <Tabs defaultActiveKey="1" items={tabItems} onChange={onChangeTab} activeKey={activeKey} />
        </>
    )
}


