import React, { useRef, useEffect, useContext, useState } from 'react';
import { ConfigProvider, Menu, Layout, Spin, theme  } from 'antd';
import { SettingOutlined, EditOutlined } from '@ant-design/icons';
import '../index.css';
import '../App.css';
import dayjs from 'dayjs';
import 'dayjs/locale/ko';
import locale from 'antd/locale/ko_KR';
import CalculateFormat from './calculations/CalculateFormat';
import CalculateCreate from './calculations/CalculateCreate';
import OutputPage from './calculations/OutputPage';

export default function Calculate(props_) {
 
  const { Content, Sider } = Layout;

  const [searchFlag, setSearchFlag] = useState(false);
  const [current, setCurrent] = useState('register');

  const {
    token: { colorBgContainer, borderRadiusLG },
  } = theme.useToken();

  const items = [
    {
      label: '포맷 설정',
      key: 'format',
      icon: <SettingOutlined />,
    },
    {
      label: '개별 등록',
      key: 'register',
      icon: <EditOutlined />,
    },

    {
      label: '세입/세출 관리',
      key: 'foodExpense',
      icon: <EditOutlined />,
    },
    // {
    //   label: '식품비세출(예산별)',
    //   key: 'foodExpenseByBudget',
    //   icon: <EditOutlined />,
    // },
    // {
    //   label: '식품비 세입',
    //   key: 'foodIncome',
    //   icon: <EditOutlined />,
    // },
    // {
    //   label: '운영비세입',
    //   key: 'operationIncome',
    //   icon: <EditOutlined />,
    // },
    // {
    //   label: '예산',
    //   key: 'budget',
    //   icon: <EditOutlined />,
    // },
  ];

  useEffect(() => {
   
  }, []);

  const onClick = (e) => {
    setCurrent(e.key);
  };

  return (
    <div className='main-container'>
      <Spin spinning={searchFlag} size="large">
        <ConfigProvider
          locale={locale}
          theme={{
            components: {
              Table: {
                footerBg: "#FFF2F2"
              },
            },
          }}
        >
          <Layout>
            <div style={{ padding: '16px 24px' }}>
              <Layout
                style={{
                  padding: '7px 3px',
                  minHeight : 'calc(100vh - 100px)',
                  background: colorBgContainer,
                  borderRadius: borderRadiusLG,
                }}
              >
                <Sider width={200} style={{ background: colorBgContainer }} >
                  <Menu
                    mode="inline"
                    defaultSelectedKeys={[current]}
                    style={{ height: '100%' }}
                    onClick={onClick}
                    items={items}
                  />
                </Sider>

                <Content
                  style={{
                    padding: '0 24px',
                    minHeight: 280,
                  }}
                >
                  <div>
                    {
                      current === "format" ?
                        <CalculateFormat />
                      :
                      current === "register" ?
                        <CalculateCreate />
                      :
                        <OutputPage/>
                    }
                  </div>
                </Content>
              </Layout>
            </div>
          </Layout>
        </ConfigProvider>
      </Spin>
    </div>
  )
}


