import '../../App.css';
import React, { useRef, useMemo, useEffect, useContext, useState } from 'react';
import axios from "axios";
import { Modal, Tabs, Button, notification, Spin, Checkbox, Popconfirm, Select, Tooltip, theme } from 'antd';
import dayjs from 'dayjs';
import 'dayjs/locale/ko';
import locale from 'antd/locale/ko_KR';
import { SettingOutlined, EditOutlined, PlusOutlined, InboxOutlined } from '@ant-design/icons';
import '../../index.css';
import TableForm from './TableForm';

export default function CalculateFormat(props_) {
  const [api, contextHolder] = notification.useNotification();

  const [searchFlag, setSearchFlag] = useState(false);
  const [dataSource, setDataSource] = useState([]);

  const [activeKey, setActiveKey] = useState('expense');

  useEffect(() => {
    getFormat();
  }, [activeKey]);

  const getFormat = () => {
    const parameter = {
      folderName: 'db',
      fileName: `${activeKey}Format.json`
    };

    setSearchFlag(true);

    axios.post('http://localhost:5000/getFileData', parameter)
      .then(res => {
        setDataSource(res.data);
        setSearchFlag(false);
      })
      .catch(error => {
        console.error(error);
        setDataSource([]);
        setSearchFlag(false);
      });

  }

  function saveCalculateFormat() {
    const parameter = {
      folderName: 'db',
      fileName: `${activeKey}Format.json`,
      data: dataSource,
    };

    setSearchFlag(true);

    axios.post('http://localhost:5000/setFileData', parameter)
      .then(response => {
        setSearchFlag(false);
        openNotification();
      })
      .catch(error => {
        console.error(error);
        setSearchFlag(false);
        openNotification(false);
      });
  }

  const openNotification = (isSuccess = true) => {
    api.success({
      message: isSuccess ? '저장 완료' : '저장 실패',
      description:
        isSuccess ? '저장이 완료되었습니다.' : '저장에 실패했습니다.',
      placement: 'top',
      duration: 2,
    });
  };

  const handleDelete = (key) => {
    const newData = dataSource.filter((item) => item.key !== key);
    setDataSource(newData);
  };

  const defaultColumns = [
    {
      title: '구분',
      dataIndex: 'schoolName',
      editable: true,
      width: '10%',
    },
    {
      title: '업체군',
      dataIndex: 'class',
      editable: true,
      width: '10%',
    },

    {
      title: '낙찰금액',
      dataIndex: 'price1',
      editable: true,
      width: '15%',
      isNumber: true,
    },
    {
      title: '학교자부담',
      dataIndex: 'price2',
      editable: true,
      width: '15%',
      isNumber: true,
    },
    {
      title: '보조금',
      dataIndex: 'price3',
      editable: true,
      width: '15%',
      isNumber: true,
    },

    {
      title: '총계',
      dataIndex: 'sumTotal',
      width: '15%',
      isNumber: true,
    },
    {
      title: '추가 기능',
      dataIndex: 'operation',
      width: '10%',
      render: (_, record) =>
        dataSource.length >= 1 ? (
          <Popconfirm title="Sure to delete?" onConfirm={() => handleDelete(record.key)}>
            <a>Delete</a>
          </Popconfirm>
        ) : null,
    }
  ];



  const defaultColumns1 = [
    {
      title: '회천',
      dataIndex: 'schoolName',
      editable: true,
      width: '10%',
    },
    {
      title: '급',
      dataIndex: 'class',
      editable: true,
      width: '20%',
    },
    {
      title: '식품비',
      dataIndex: 'price',
      editable: true,
      width: '15%',
      isNumber: true,
    },
    {
      title: '급식일수 일괄적용',
      dataIndex: 'isAllAdapt',
      width: '5%',
      render: (_, record) => <Checkbox checked={record.isAllAdapt} onChange={(e) => {
        setDataSource((prevData) =>
          prevData.map((item) =>
            item.key === record.key ? { ...item, isAllAdapt: e.target.checked } : item
          )
        );
      }} />,
    },
    {
      title: '급식일수',
      dataIndex: 'date',
      editable: true,
      width: '10%',
      isNumber: true,
    },
    {
      title: '학생 수',
      dataIndex: 'count',
      editable: true,
      width: '10%',
      isNumber: true,
    },
    {
      title: '총액',
      dataIndex: 'total',
      width: '15%',
      isNumber: true,
    },
    {
      title: '추가 기능',
      dataIndex: 'operation',
      width: '10%',
      render: (_, record) =>
        dataSource.length >= 1 ? (
          <Popconfirm title="Sure to delete?" onConfirm={() => handleDelete(record.key)}>
            <a>Delete</a>
          </Popconfirm>
        ) : null,
    }
  ];

  const defaultColumns2 = [
    {
      title: '구분',
      dataIndex: 'schoolName',
      editable: true,
      width: '10%',
    },
    {
      title: '보조/자부담',
      dataIndex: 'assistance',
      editable: true,
      width: '10%',
    },
    {
      title: '급',
      dataIndex: 'class',
      editable: true,
      width: '15%',
    },
    {
      title: '식품비',
      dataIndex: 'price',
      editable: true,
      width: '15%',
      isNumber: true,
    },
    {
      title: '급식일수 일괄적용',
      dataIndex: 'isAllAdapt',
      width: '5%',
      render: (_, record) => <Checkbox checked={record.isAllAdapt} onChange={(e) => {
        setDataSource((prevData) =>
          prevData.map((item) =>
            item.key === record.key ? { ...item, isAllAdapt: e.target.checked } : item
          )
        );
      }} />,
    },
    {
      title: '급식일수',
      dataIndex: 'date',
      editable: true,
      width: '10%',
      isNumber: true,
    },
    {
      title: '학생 수',
      dataIndex: 'count',
      editable: true,
      width: '10%',
      isNumber: true,
    },
    {
      title: '총액',
      dataIndex: 'total',
      width: '15%',
      isNumber: true,
    },

    {
      title: '추가 기능',
      dataIndex: 'operation',
      width: '10%',
      render: (_, record) =>
        dataSource.length >= 1 ? (
          <Popconfirm title="Sure to delete?" onConfirm={() => handleDelete(record.key)}>
            <a>Delete</a>
          </Popconfirm>
        ) : null,
    }

  ];

  const defaultColumns3 = [
    {
      title: '회천',
      dataIndex: 'schoolName',
      editable: true,
      width: '10%',
    },
    {
      title: '급',
      dataIndex: 'class',
      editable: true,
      width: '20%',
    },
    {
      title: '운영비',
      dataIndex: 'price',
      editable: true,
      width: '15%',
      isNumber: true,
    },
    {
      title: '급식일수 일괄적용',
      dataIndex: 'isAllAdapt',
      width: '5%',
      render: (_, record) => <Checkbox checked={record.isAllAdapt} onChange={(e) => {
        setDataSource((prevData) =>
          prevData.map((item) =>
            item.key === record.key ? { ...item, isAllAdapt: e.target.checked } : item
          )
        );
      }} />,
    },
    {
      title: '급식일수',
      dataIndex: 'date',
      editable: true,
      width: '10%',
      isNumber: true,
    },
    {
      title: '학생 수',
      dataIndex: 'count',
      editable: true,
      width: '10%',
      isNumber: true,
    },
    {
      title: '총액',
      dataIndex: 'total',
      width: '15%',
      isNumber: true,
    },
    {
      title: '추가 기능',
      dataIndex: 'operation',
      width: '10%',
      render: (_, record) =>
        dataSource.length >= 1 ? (
          <Popconfirm title="Sure to delete?" onConfirm={() => handleDelete(record.key)}>
            <a>Delete</a>
          </Popconfirm>
        ) : null,
    }
  ];

  const items = [

    {
      key: 'expense',
      label: '세출',
      children: (
        <TableForm
          dataSource={dataSource}
          setDataSource={setDataSource}
          defaultColumns={defaultColumns}
        />
      ),
    },
    {
      key: 'foodIncome',
      label: '식품비',
      children: (
        <TableForm
          dataSource={dataSource}
          setDataSource={setDataSource}
          defaultColumns={defaultColumns1}
          isRoundUp={true}
        />
      ),
    },
    {
      key: 'foodIncomeEco',
      label: '친환경',
      children: (<TableForm
        dataSource={dataSource}
        setDataSource={setDataSource}
        defaultColumns={defaultColumns2}
      />),
    },
    {
      key: 'operatingCost',
      label: '운영비',
      children: (<TableForm
        dataSource={dataSource}
        setDataSource={setDataSource}
        defaultColumns={defaultColumns3}
      />),
    },
  ];

  const onChange = key => {
    console.log(key);
    setActiveKey(key);
  };

  return (
    <>
      <Spin spinning={searchFlag} size="large">
        <h2 style={{ marginTop: "5px" }}>기본 포맷 작성</h2>

        <Tabs defaultActiveKey="1" items={items} onChange={onChange} activeKey={activeKey} />

        <div style={{ display: "flex", justifyContent: "end", width: "100%", margin: "15px 0" }}>
          <Button type="primary" onClick={saveCalculateFormat}>저장</Button>
        </div>
      </Spin>

      {contextHolder}

    </>
  )
}


